import { api } from '@/lib/api'

class SitePackageService {
  async list(params: Record<string, any> = {}) {
    const response = await api.get('/site-packages', { params })
    return response.data
  }

  /** Notification wizard registry (categories, types, field library) from MongoDB. */
  async getNotificationTemplates() {
    const response = await api.get('/notification-templates')
    return response.data
  }

  async createSitePackage(payload: any) {
    const response = await api.post('/site-packages', payload)
    return response.data
  }

  // Legacy alias used by the standalone module
  async create(payload: any) {
    return this.createSitePackage(payload)
  }

  /** `scope` is required: packages are only readable in the matching study + site workspace. */
  async getById(id: string, scope: { study: string; site: string }) {
    const response = await api.get(`/site-packages/${id}`, {
      params: { study: scope.study, site: scope.site },
    })
    return response.data
  }

  async delete(id: string, scope: { study: string; site: string }) {
    const response = await api.delete(`/site-packages/${id}`, {
      params: { study: scope.study, site: scope.site },
    })
    return response.data
  }

  async update(id: string, updates: any, scope: { study: string; site: string }) {
    const response = await api.patch(`/site-packages/${id}`, updates, {
      params: { study: scope.study, site: scope.site },
    })
    return response.data
  }

  async uploadSitePackageDocument(
    packageId: string,
    documentName: string,
    file: File,
    scope: { studyId: string; siteId: string },
    documentType?: string,
    tmfDocumentId?: string,
    source?: string,
    onUploadProgress?: (pct: number) => void,
  ) {
    if (!scope?.studyId || !scope?.siteId) {
      throw new Error('Study and site scope are required for document upload')
    }
    const form = new FormData()
    form.append('file', file)
    form.append('documentName', documentName)
    form.append('study_id', scope.studyId)
    form.append('site_id', scope.siteId)
    if (documentType) form.append('documentType', documentType)
    if (tmfDocumentId) form.append('tmfDocumentId', tmfDocumentId)
    if (source) form.append('source', source)

    const response = await api.post(`/site-packages/${packageId}/documents`, form, {
      headers: { 'Content-Type': 'multipart/form-data' },
      onUploadProgress: (progressEvent) => {
        const total = progressEvent.total || 0
        const percentCompleted = total
          ? Math.round((progressEvent.loaded * 100) / total)
          : 0
        if (onUploadProgress) onUploadProgress(percentCompleted)
      },
    })

    return { success: true, data: response.data }
  }

  async uploadFile(
    file: File,
    studyId: string,
    siteId: string,
    documentType: string,
    onUploadProgress?: (pct: number) => void
  ) {
    const form = new FormData()
    form.append('file', file)
    form.append('study_id', studyId)
    form.append('site_id', siteId)
    form.append('document_type', documentType)
    const response = await api.post('/site-packages/upload', form, {
      headers: { 'Content-Type': 'multipart/form-data' },
      onUploadProgress: (progressEvent) => {
        const total = progressEvent.total || 0
        const percentCompleted = total
          ? Math.round((progressEvent.loaded * 100) / total)
          : 0
        if (onUploadProgress) onUploadProgress(percentCompleted)
      },
    })
    return response.data
  }

  async generateSitePackageDocument(params: {
    studyId: string
    siteId: string
    documentType: string
    documentName?: string
    outputFormat?: 'docx' | 'pdf'
    requiredDocumentNames?: string[]
  }) {
    const form = new FormData()
    form.append('study_id', params.studyId)
    form.append('site_id', params.siteId)
    form.append('document_type', params.documentType)
    if (params.documentName) form.append('document_name', params.documentName)
    if (params.outputFormat) form.append('output_format', params.outputFormat)
    if (Array.isArray(params.requiredDocumentNames) && params.requiredDocumentNames.length > 0) {
      form.append('required_document_names', JSON.stringify(params.requiredDocumentNames))
    }

    try {
      const response = await api.post('/site-packages/generate-document', form, {
        headers: { 'Content-Type': 'multipart/form-data' },
        responseType: 'blob',
      })
      const headers = response.headers || {}
      const contentDisposition = headers['content-disposition'] || headers['Content-Disposition'] || ''
      const fromHeader = /filename=\"?([^\"]+)\"?/i.exec(String(contentDisposition))?.[1]
      const outputExt = params.outputFormat === 'pdf' ? 'pdf' : 'docx'
      const generatedName = headers['x-generated-filename'] || fromHeader || `${params.documentType}.${outputExt}`
      const mimeType =
        headers['content-type'] ||
        headers['Content-Type'] ||
        'application/vnd.openxmlformats-officedocument.wordprocessingml.document'

      return {
        blob: response.data as Blob,
        filename: String(generatedName),
        mimeType: String(mimeType),
      }
    } catch (err: any) {
      const data = err?.response?.data
      if (data instanceof Blob) {
        const text = await data.text()
        try {
          const parsed = JSON.parse(text)
          const detail = parsed?.error || parsed?.detail || text
          throw new Error(typeof detail === 'string' ? detail : JSON.stringify(detail))
        } catch {
          throw new Error(text || err?.message || 'Failed to generate document')
        }
      }
      throw err instanceof Error ? err : new Error(String(err))
    }
  }

  async generateCoverLetterAssets(params: {
    studyId: string
    siteId: string
    documentType: string
    documentName?: string
    requiredDocumentNames?: string[]
    protocolMetadata?: {
      protocol_number?: string | null
      study_title?: string | null
      study_description?: string | null
      version?: string | number | null
      date?: string | null
    } | null
  }) {
    const form = new FormData()
    form.append('study_id', params.studyId)
    form.append('site_id', params.siteId)
    form.append('document_type', params.documentType)
    if (params.documentName) form.append('document_name', params.documentName)
    if (Array.isArray(params.requiredDocumentNames) && params.requiredDocumentNames.length > 0) {
      form.append('required_document_names', JSON.stringify(params.requiredDocumentNames))
    }
    if (params.protocolMetadata && typeof params.protocolMetadata === 'object') {
      form.append('protocol_metadata', JSON.stringify(params.protocolMetadata))
    }

    const response = await api.post('/site-packages/generate-cover-letter-assets', form, {
      headers: { 'Content-Type': 'multipart/form-data' },
    })
    const payload = response.data
    if (payload && typeof payload === 'object' && 'data' in payload) {
      return (payload as any).data
    }
    return payload
  }

  async extractProtocolMetadata(params: { fileUrl: string; maxPages?: number }) {
    const response = await api.post('/site-packages/extract-protocol-metadata', {
      fileUrl: params.fileUrl,
      maxPages: params.maxPages ?? 5,
    })
    const payload = response.data
    if (payload && typeof payload === 'object' && 'data' in payload) {
      return (payload as any).data
    }
    return payload
  }

  async getCoverLetterOnlyOfficeConfig(params: {
    packageId: string
    studyId: string
    siteId: string
    documentName?: string
  }) {
    const response = await api.get(`/site-packages/${params.packageId}/cover-letter-onlyoffice-config`, {
      params: {
        study: params.studyId,
        site: params.siteId,
        ...(params.documentName ? { document_name: params.documentName } : {}),
      },
    })
    return response.data
  }

  async getCoverLetterOnlyOfficeStatus(params: {
    packageId: string
    studyId: string
    siteId: string
    documentName?: string
  }) {
    const response = await api.get(`/site-packages/${params.packageId}/cover-letter-onlyoffice-status`, {
      params: {
        study: params.studyId,
        site: params.siteId,
        ...(params.documentName ? { document_name: params.documentName } : {}),
      },
    })
    return response.data
  }

  async presign(fileUrl: string) {
    const response = await api.post('/site-packages/presign', { fileUrl })
    return response.data
  }

  /**
   * Download blob bytes via CRM backend (avoids browser CORS on Azure SAS URLs when building ZIPs).
   */
  async fetchDocumentWithMeta(fileUrl: string) {
    try {
      const response = await api.post('/site-packages/fetch-document', { fileUrl }, { responseType: 'blob' })
      const headers = response.headers || {}
      const headerContentType = headers['content-type'] || headers['Content-Type']
      const blob = response.data as Blob
      return {
        blob,
        headers,
        status: response.status,
        contentType: String(headerContentType || blob?.type || ''),
      }
    } catch (err: any) {
      const raw = err?.response?.data
      if (raw && typeof raw === 'object' && !(raw instanceof Blob) && (raw as any).detail) {
        const d = (raw as any).detail
        throw new Error(typeof d === 'string' ? d : JSON.stringify(d))
      }
      const data = raw
      if (data instanceof Blob) {
        const text = await data.text()
        let msg = err?.message || 'Download failed'
        try {
          const j = JSON.parse(text)
          if (j?.error) msg = String(j.error)
          else if (j?.detail) {
            msg = typeof j.detail === 'string' ? j.detail : JSON.stringify(j.detail)
          }
        } catch {
          if (text) msg = text.slice(0, 400)
        }
        throw new Error(msg)
      }
      throw err instanceof Error ? err : new Error(String(err))
    }
  }

  async fetchDocumentBlob(fileUrl: string) {
    const { blob } = await this.fetchDocumentWithMeta(fileUrl)
    return blob
  }

  /** Global IRB list: GET /irbs → { success, data: { id, name, unique_code, country }[] } */
  async listIrbs(params?: { country?: string }) {
    const response = await api.get('/irbs', {
      params: params?.country ? { country: params.country } : undefined,
    })
    return response.data
  }

  async getSiteIrbMapping(siteId: string) {
    const response = await api.get('/site-irb-mapping', {
      params: { site_id: siteId },
    })
    return response.data
  }

  /** IRB linked to this site (legacy alias). */
  async getSiteIrbForSite(siteId: string) {
    const response = await api.get('/site-irb-mapping/for-site', {
      params: { site_id: siteId },
    })
    return response.data
  }

  async saveSiteIrbMapping(payload: { site_id: string; irb_id: number }) {
    const response = await api.post('/site-irb-mapping', payload)
    return response.data
  }

  /** Resolve dashboard study id (UUID or external study_id) to Study UUID */
  async resolveStudyUuid(studyValue: string): Promise<string | null> {
    if (!studyValue?.trim()) return null
    const v = studyValue.trim()
    if (
      /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$/.test(v)
    ) {
      return v
    }
    const response = await api.get('/studies')
    const list = Array.isArray(response.data) ? response.data : []
    const s = list.find(
      (x: any) => String(x.study_id) === String(v) || String(x.id) === String(v)
    )
    return s?.id ? String(s.id) : null
  }

  async getIrbRequirements(irbId: number) {
    const response = await api.get('/irb-requirements', { params: { irb_id: irbId } })
    return response.data
  }

  async getSitesForStudy(studyId: string) {
    const response = await api.get('/sites', { params: { study_id: studyId } })
    return response.data
  }
}

export default new SitePackageService()

